import json
# Four-by-four array of solid interior colors, surrounded by 4 frames.
colors = [
    [3,2,2,3],
    [2,8,8,2],
    [3,2,2,3],
    [2,8,8,2],
]
g = [[0]*30 for _ in range(30)]
starts = [1,8,15,22,29]
# Recreate all visible framed tiles, including the clipped bottom row and rightmost column.
for tr, r0 in enumerate(starts):
    for tc, c0 in enumerate(starts):
        for dr in range(5):
            r = r0+dr
            if r >= 30: continue
            for dc in range(5):
                c = c0+dc
                if c >= 30: continue
                # Incomplete last tile row/column has only its visible frame edge.
                if tr == 4 or tc == 4 or dr in (0,4) or dc in (0,4):
                    g[r][c] = 4
                else:
                    g[r][c] = colors[tr][tc]
# Join matching interior colors across blank separators, preserving tile contents.
# Horizontal joins across all gaps between repeated colors within each tile row.
for tr in range(4):
    for dr in (1,2,3):
        r = starts[tr] + dr
        vals = colors[tr]
        for col in set(vals):
            inds = [i for i,v in enumerate(vals) if v == col]
            if len(inds) >= 2:
                for tc in range(min(inds), max(inds)):
                    cstart = starts[tc]+5
                    for c in range(cstart, starts[tc+1]):
                        if g[r][c] == 0: g[r][c] = col
# Vertical joins analogously.
for tc in range(4):
    for dc in (1,2,3):
        c = starts[tc] + dc
        vals = [colors[tr][tc] for tr in range(4)]
        for col in set(vals):
            inds = [i for i,v in enumerate(vals) if v == col]
            if len(inds) >= 2:
                for tr in range(min(inds), max(inds)):
                    rstart = starts[tr]+5
                    for r in range(rstart, starts[tr+1]):
                        if g[r][c] == 0: g[r][c] = col
print(json.dumps(g, separators=(',',':')))

